# Sample code to validate CSV format
import csv
import io

def validate_csv(csv_string):
    try:
        csv_file = io.StringIO(csv_string)
        reader = csv.DictReader(csv_file)
        for row in reader:
            assert 'name' in row and 'description' in row and 'price' in row, "Missing required columns"
            assert isinstance(float(row['price']), float), "Price must be a number"
        return True
    except Exception as e:
        return str(e)

